def read_expenses(count):
    data = {}
    for _ in range(count):
        name = input()
        try:
            price = float(input())
        except ValueError:
            print("Маблағ нодуруст аст")
            continue
        data[name] = price
    return data

def report(data):
    total = sum(data.values())
    biggest = max(data, key=data.get)
    print(f"Ҷамъ: {total:.2f}")
    print(f"Калонтарин: {biggest}")

report(read_expenses(int(input())))
